do $$declare definition text;begin select pg_get_functiondef('club_selection_private.match_results_api(uuid,text,jsonb)'::regprocedure) into definition; if position('return jsonb_build_object(''playhq'',' in definition)=0 then raise exception 'Unexpected results function';end if;execute replace(definition,'return jsonb_build_object(''playhq'',','return jsonb_build_object(''can_review'',coach and exists(select 1 from jsonb_array_elements(club_batting_private.review_fixture_options(c)) opt where opt->>''id''=fid::text),''playhq'',');end $$;
